Author = namedtuple('Author', 'name sort')


def is_relators_role(props, q):
    role = props.get('role')
    if role:
        scheme_ns, scheme, role = role
        return role.lower() == q and (scheme_ns is None or (scheme_ns, scheme) == (reserved_prefixes['marc'], 'relators'))
    return False


